export type TranslationKey = keyof typeof translations.tr | keyof typeof featuresTranslations.tr | keyof typeof dailyMoodTranslations.tr | keyof typeof premiumTranslations.tr | keyof typeof onboardingTranslations.tr | keyof typeof onboardingModeTranslations.tr | keyof typeof settingsTranslations.tr | keyof typeof coachRatingTranslations.tr | keyof typeof coachAtmosphereTranslations.tr | keyof typeof profileEditTranslations.tr | keyof typeof workoutPlanTranslations.tr | keyof typeof exerciseFormTranslations.tr | keyof typeof premiumPlanTranslations.tr | keyof typeof streakUiTranslations.tr | keyof typeof themeTranslations.tr | keyof typeof trainingLoadTranslations.tr;

const workoutReminderDescriptions: Record<Language, string> = {
  tr: 'Antrenman günlerinde saat 09:00’da o günün antrenmanını ve süresini hatırlat.',
  en: 'Remind me at 9:00 AM on training days with that day’s workout and duration.',
  de: 'Erinnere mich an Trainingstagen um 09:00 Uhr mit dem Training und der Dauer des Tages.',
  fr: 'Rappelle-moi à 9 h les jours d’entraînement avec la séance et sa durée.',
  es: 'Recuérdame a las 9:00 los días de entrenamiento con la sesión y su duración.',
};

const workoutReminderTemplates: Record<Language, (workoutName: string, duration: number) => string> = {
  tr: (workoutName, duration) => `Bugün ${workoutName} var. ${duration} dakikalık antrenmanın seni bekliyor.`,
  en: (workoutName, duration) => `Today is ${workoutName}. Your ${duration}-minute workout is waiting.`,
  de: (workoutName, duration) => `Heute steht ${workoutName} an. Dein ${duration}-minütiges Training wartet.`,
  fr: (workoutName, duration) => `Aujourd’hui : ${workoutName}. Ta séance de ${duration} minutes t’attend.`,
  es: (workoutName, duration) => `Hoy toca ${workoutName}. Te espera una sesión de ${duration} minutos.`,
};

export function formatWorkoutReminder(language: Language, workoutName: string, duration: number) {
  return workoutReminderTemplates[language](workoutName, duration);
}

function applyCurrentBrand(value: string): string {
  return value.replace(/Forge Fit/g, 'GainMode').replace(/FORGE FIT/g, 'GAINMODE').replace(/Forge-Fit/g, 'GainMode');
}

export function translate(language: Language, key: TranslationKey): string {
  if (key === 'premiumShort' || key === 'premiumModalEyebrow') return subscriptionAccessLabel[language];
  if (key === 'photoAiBox') return photoAnalysisStatusCopy[language];
  if (key in themeTranslations.tr) return themeTranslations[language][key as keyof typeof themeTranslations.tr];
  if (key in trainingLoadTranslations.tr) return trainingLoadTranslations[language][key as keyof typeof trainingLoadTranslations.tr];
  if (key === 'workoutReminderDescription') return workoutReminderDescriptions[language];
  if (key === 'premiumPriceOptions') return applyCurrentBrand(getPremiumPreviewPriceOptions(language));
  if (key in featuresTranslations.tr) {
    const featureCopy = featuresTranslations[language] ?? featuresTranslations.en;
    return applyCurrentBrand(featureCopy[key as keyof typeof featuresTranslations.tr] ?? featuresTranslations.en[key as keyof typeof featuresTranslations.tr] ?? key);
  }
  if (key in dailyMoodTranslations.tr) {
    const moodCopy = dailyMoodTranslations[language] ?? dailyMoodTranslations.en;
    return applyCurrentBrand(moodCopy[key as keyof typeof dailyMoodTranslations.tr] ?? dailyMoodTranslations.en[key as keyof typeof dailyMoodTranslations.tr] ?? key);
  }
  if (key in premiumPlanTranslations.tr) return applyCurrentBrand(premiumPlanTranslations[language][key as keyof typeof premiumPlanTranslations.tr]);
  if (key in streakUiTranslations.tr) return applyCurrentBrand(streakUiTranslations[language][key as keyof typeof streakUiTranslations.tr]);
  if (key in exerciseFormTranslations.tr) return exerciseFormTranslations[language][key as keyof typeof exerciseFormTranslations.tr];
  if (key === 'premiumFeature1') return applyCurrentBrand(premiumFeatureOneCopy[language]);
  if (key === 'premiumFeature2') return applyCurrentBrand(premiumBenefitCopy[language].photo);
  if (key === 'premiumFeature3') return applyCurrentBrand(premiumBenefitCopy[language].coach);
  if (key === 'coachLimitReached') return applyCurrentBrand(usageLimitCopy[language].coach);
  if (key === 'photoLimitReached') return applyCurrentBrand(usageLimitCopy[language].photo);
  if (key === 'homeEquipmentDetailsHint') return applyCurrentBrand(homeEquipmentDetailsCopy[language].hint);
  if (key === 'homeEquipmentDetailsPlaceholder') return applyCurrentBrand(homeEquipmentDetailsCopy[language].placeholder);
  if (key in onboardingModeTranslations.tr) return applyCurrentBrand(onboardingModeTranslations[language][key as keyof typeof onboardingModeTranslations.tr]);
  if (key === 'onboardingIntro2') return applyCurrentBrand(onboardingIntro2Translations[language]);
  if (key === 'onboardingTitle') return applyCurrentBrand(onboardingMotivationTranslations[language].title);
  if (key === 'onboardingIntro') return applyCurrentBrand(onboardingMotivationTranslations[language].intro);
  if (key === 'welcomeSubtitle') return applyCurrentBrand(onboardingMotivationTranslations[language].welcomeSubtitle);
  if (key in profileEditTranslations.tr) {
    const profileEdit = profileEditTranslations[language] as Record<string, string>;
    const fallbackProfileEdit = profileEditTranslations.en as Record<string, string>;
    return applyCurrentBrand(profileEdit[key] ?? fallbackProfileEdit[key] ?? key);
  }
  if (key in workoutPlanTranslations.tr) {
    const workoutPlan = workoutPlanTranslations[language] as Record<string, string>;
    const fallbackWorkoutPlan = workoutPlanTranslations.en as Record<string, string>;
    return applyCurrentBrand(workoutPlan[key] ?? fallbackWorkoutPlan[key] ?? key);
  }
  if (key in coachRatingTranslations.tr) {
    const ratingCopy = coachRatingTranslations[language] as Record<string, string>;
    const fallbackRating = coachRatingTranslations.en as Record<string, string>;
    return applyCurrentBrand(ratingCopy[key] ?? fallbackRating[key] ?? key);
  }
  if (key in coachAtmosphereTranslations.tr) {
    const atmosphereCopy = coachAtmosphereTranslations[language] as Record<string, string>;
    const fallbackAtmosphere = coachAtmosphereTranslations.en as Record<string, string>;
    return applyCurrentBrand(atmosphereCopy[key] ?? fallbackAtmosphere[key] ?? key);
  }
  const base = translations[language] as Record<string, string>;
  const fallbackBase = translations.en as Record<string, string>;
  const extra = onboardingTranslations[language] as Record<string, string>;
  const fallbackExtra = onboardingTranslations.en as Record<string, string>;
  const premium = premiumTranslations[language] as Record<string, string>;
  const fallbackPremium = premiumTranslations.en as Record<string, string>;
  const settings = settingsTranslations[language] as Record<string, string>;
  const fallbackSettings = settingsTranslations.en as Record<string, string>;
  return applyCurrentBrand(base[key] ?? extra[key] ?? premium[key] ?? settings[key] ?? fallbackBase[key] ?? fallbackExtra[key] ?? fallbackPremium[key] ?? fallbackSettings[key] ?? key);
}